  "ương":         {hanoi: "ɯɤŋ",        quangnam: "ɨːŋ",        saigon: "ɯːŋ"},
  "ươc":          {hanoi: "ɯɤk",        quangnam: "ɨːk",        saigon: "ɯːk"},

